    json_data = item.get("json", {})

    job_description = json_data.get("Job Description", "")

    for key, file in binary_files.items():
        result.append({
            "json": {
                "Job Description": job_description,
                "resume_file_name": file.get("fileName", key)
            },
            "binary": {
                "resume": file
            }
        })

return result

# Get all candidates reaching this node
candidates = _items


def get_score(item):
    try:
        return float(
            item.get("json", {}).get("overall_score", 0)
        )
    except (TypeError, ValueError):
        return 0


# Sort highest overall score first
candidates.sort(
    key=get_score,
    reverse=True
)


# Add rank
results = []

for index, candidate in enumerate(candidates):

    data = candidate.get("json", {}).copy()

    data["rank"] = index + 1

    results.append({
        "json": data
    })


return results

