items = _items


# --------------------------------------------------
# Helper functions
# --------------------------------------------------

def esc(value):
    """Basic HTML escaping."""
    if value is None:
        return ""

    value = str(value)

    return (
        value
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#039;")
    )


def get_json(item):
    if isinstance(item, dict):
        return item.get("json", {})
    return {}


def get_score(data, field):
    try:
        value = int(float(data.get(field, 0)))
        return max(0, min(100, value))
    except:
        return 0


def format_relevant_exp(value):
    """Convert candidate_years to a clean display value."""
    if value is None or value == "":
        return "Not stated"

    try:
        number = float(value)

        if number == int(number):
            number = int(number)

        return f"{number} years"
    except:
        value = str(value).strip()

        if "year" in value.lower():
            return value

        return f"{value} years"


# --------------------------------------------------
# Get candidates
# --------------------------------------------------

candidates = []

for item in items:
    data = get_json(item)

    candidates.append({
        "candidate_name": data.get("candidate_name", "Not stated"),
        "degree": data.get("degree", "Not stated"),

        # Experience
        "total_experience": data.get("years_exp", "Not stated"),
        "relevant_experience": format_relevant_exp(
            data.get("candidate_years")
        ),

        # Scores
        "overall_score": get_score(data, "overall_score"),
        "tech_score": get_score(data, "tech_score"),
        "proj_score": get_score(data, "proj_score"),
        "edu_score": get_score(data, "edu_score"),
        "exp_score": get_score(data, "exp_score"),

        # Summary
        "experience_match": data.get("experience_match", ""),
        "recruiter_takeaway": data.get("recruiter_takeaway", "")
    })


# --------------------------------------------------
# Rank candidates
# --------------------------------------------------

candidates.sort(
    key=lambda x: x["overall_score"],
    reverse=True
)

for index, candidate in enumerate(candidates):
    candidate["rank"] = index + 1


# --------------------------------------------------
# Build candidate rows
