// Process every candidate returned by the LLM
const inputItems = $input.all();

const clamp = (val) => {
  const num = Math.round(Number(val));

  return Number.isNaN(num)
    ? 0
    : Math.max(0, Math.min(100, num));
};

const toNum = (val) => {
  if (
    val === null ||
    val === undefined ||
    val === '' ||
    Number.isNaN(Number(val))
  ) {
    return null;
  }

  return Number(val);
};

const results = [];

for (let i = 0; i < inputItems.length; i++) {

  // -----------------------------------
  // 1. Get LLM response
  // -----------------------------------

  const rawText =
    inputItems[i].json.text ||
    inputItems[i].json.content ||
    '';

  let cleanText = String(rawText).trim();

  // Remove markdown fences
  if (cleanText.startsWith('```json')) {
    cleanText = cleanText.slice(7);
  } else if (cleanText.startsWith('```')) {
    cleanText = cleanText.slice(3);
  }

  if (cleanText.endsWith('```')) {
    cleanText = cleanText.slice(0, -3);
  }

  cleanText = cleanText.trim();

  // Extract JSON object defensively
  const firstBrace = cleanText.indexOf('{');
  const lastBrace = cleanText.lastIndexOf('}');

  if (
    firstBrace !== -1 &&
    lastBrace !== -1 &&
    lastBrace > firstBrace
  ) {
    cleanText = cleanText.substring(
      firstBrace,
      lastBrace + 1
    );
  }

  // -----------------------------------
  // 2. Parse candidate JSON
  // -----------------------------------

  let candidate;

  try {

    candidate = JSON.parse(cleanText);

  } catch (error) {

    results.push({
      json: {

        candidate_number: i + 1,

        candidate_name: 'Parsing Error',

        overall_score: 0,

        tech_score: 0,
        proj_score: 0,
        edu_score: 0,
        exp_score: 0,

        degree: 'Not stated',

        years_exp: 'Not stated',

        candidate_years: null,

        required_years: null,

        experience_match:
          'Unable to parse candidate evaluation.',

        matched_qualifications: [],

        skill_gaps: [
          'LLM response could not be parsed.'
        ],

        recruiter_takeaway:
          `JSON parsing error: ${error.message}`,

        parsing_error: true,

        analysis_failed: false
      }
    });

    continue;
  }

  // -----------------------------------
  // 3. Clean scores
  // -----------------------------------

  let tech = clamp(candidate.tech_score);
  let proj = clamp(candidate.proj_score);
  let edu = clamp(candidate.edu_score);
  let exp = clamp(candidate.exp_score);

  const candidateYears =
    toNum(candidate.candidate_years);

  const requiredYears =
    toNum(candidate.required_years);

  // -----------------------------------
  // 4. Experience safety rules
  // -----------------------------------

  const jdRequiresExperience =
    requiredYears !== null &&
    requiredYears > 0;

  const noRelevantExperience =
    candidateYears !== null &&
    candidateYears === 0;

  const lacksRequiredExperience =
    jdRequiresExperience &&
    noRelevantExperience;

  // JD requires experience but candidate
  // has 0 established relevant years
  if (lacksRequiredExperience) {

    exp = Math.min(exp, 15);

  } else if (
    jdRequiresExperience &&
    candidateYears !== null &&
    candidateYears < requiredYears
  ) {

    // Candidate has some relevant experience,
    // but less than the JD minimum
    const experienceCeiling =
      Math.round(
        (candidateYears / requiredYears) * 100
      );

    exp = Math.min(
      exp,
      experienceCeiling
    );
  }

  // -----------------------------------
  // 5. Overall score
  // -----------------------------------

  // Technical  = 30%
  // Projects   = 15%
  // Education  = 15%
  // Experience = 40%

  let overallScore = Math.round(
    (tech * 0.30) +
    (proj * 0.15) +
    (edu * 0.15) +
    (exp * 0.40)
  );

  // Preserve your existing hard cap
  if (lacksRequiredExperience) {
    overallScore =
      Math.min(overallScore, 50);
  }

  overallScore = clamp(overallScore);

  // -----------------------------------
  // 6. Validate arrays
  // -----------------------------------

  const matchedQualifications =
    Array.isArray(candidate.matched_qualifications)
      ? candidate.matched_qualifications.slice(0, 3)
      : [];

  const skillGaps =
    Array.isArray(candidate.skill_gaps)
      ? candidate.skill_gaps.slice(0, 3)
      : [];

  // -----------------------------------
  // 7. Return clean candidate
  // -----------------------------------

  results.push({
    json: {

      candidate_number: i + 1,

      candidate_name:
        candidate.candidate_name ||
        'Not stated',

      degree:
        candidate.degree ||
        'Not stated',

      years_exp:
        candidate.years_exp ||
        'Not stated',

      candidate_years:
        candidateYears,

      required_years:
        requiredYears,

      tech_score:
        tech,

      proj_score:
        proj,

      edu_score:
        edu,

      exp_score:
        exp,

      overall_score:
        overallScore,

      experience_match:
        candidate.experience_match ||
        'Not stated',

      matched_qualifications:
        matchedQualifications,

      skill_gaps:
        skillGaps,

      recruiter_takeaway:
        candidate.recruiter_takeaway ||
        'Not stated',

      parsing_error: false,

      analysis_failed: false
    }
  });
}

return results;
